-- S10 achievements: tables. MySQL / MariaDB, utf8mb4, InnoDB. Safe to run again (IF NOT EXISTS).
-- Generated by cli/schema.php from achievements/Schema.php; edit there, not here.

-- Levels of each achievement per user: the dates of every reached level, the current value
CREATE TABLE IF NOT EXISTS `ach_level` (
  `user_id` BIGINT NOT NULL,
  `role` CHAR(1) NOT NULL,
  `achievement` VARCHAR(32) NOT NULL,
  `level` TINYINT NOT NULL DEFAULT 0,
  `dates` VARCHAR(255) NOT NULL,
  `value` DOUBLE NULL,
  `info` MEDIUMTEXT NULL,
  `updated_at` DATETIME NULL,
  PRIMARY KEY (`user_id`, `role`, `achievement`),
  KEY `ach_level_stat` (`role`, `achievement`, `level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Points and rank per user and role, ready for profiles and lists
CREATE TABLE IF NOT EXISTS `ach_score` (
  `user_id` BIGINT NOT NULL,
  `role` CHAR(1) NOT NULL,
  `points` INT NOT NULL DEFAULT 0,
  `rank_idx` TINYINT NOT NULL DEFAULT 0,
  `near` VARCHAR(255) NULL,
  `active_at` CHAR(10) NULL,
  `recalc_at` DATETIME NULL,
  PRIMARY KEY (`user_id`, `role`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Every reached level: «Последние полученные» and the level-up window
CREATE TABLE IF NOT EXISTS `ach_event` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT NOT NULL,
  `role` CHAR(1) NOT NULL,
  `achievement` VARCHAR(32) NOT NULL,
  `level` TINYINT NOT NULL,
  `day` CHAR(10) NOT NULL,
  `celebrated` TINYINT NOT NULL DEFAULT 0,
  `created_at` DATETIME NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ach_event_one` (`user_id`, `role`, `achievement`, `level`),
  KEY `ach_event_user` (`user_id`, `role`, `day`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Every reached rank
CREATE TABLE IF NOT EXISTS `ach_rank_event` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT NOT NULL,
  `role` CHAR(1) NOT NULL,
  `rank_idx` TINYINT NOT NULL,
  `day` CHAR(10) NOT NULL,
  `celebrated` TINYINT NOT NULL DEFAULT 0,
  `created_at` DATETIME NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ach_rank_event_one` (`user_id`, `role`, `rank_idx`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- The bell
CREATE TABLE IF NOT EXISTS `ach_notification` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT NOT NULL,
  `role` CHAR(1) NOT NULL,
  `type` VARCHAR(20) NOT NULL,
  `payload` TEXT NOT NULL,
  `ref` VARCHAR(64) NULL,
  `day` CHAR(10) NOT NULL,
  `unread` TINYINT NOT NULL DEFAULT 1,
  `created_at` DATETIME NULL,
  PRIMARY KEY (`id`),
  KEY `ach_notification_user` (`user_id`, `role`, `id`),
  KEY `ach_notification_ref` (`user_id`, `role`, `ref`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Who sees, the showcases, the name format in a coach showcase
CREATE TABLE IF NOT EXISTS `ach_setting` (
  `user_id` BIGINT NOT NULL,
  `audience` VARCHAR(10) NULL,
  `coach_audience` VARCHAR(10) NULL,
  `showcase` TEXT NULL,
  `coach_showcase` TEXT NULL,
  `name_format` VARCHAR(10) NULL,
  `updated_at` DATETIME NULL,
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- A student lets his coach show his achievements: pending / yes / no
CREATE TABLE IF NOT EXISTS `ach_consent` (
  `coach_id` BIGINT NOT NULL,
  `athlete_id` BIGINT NOT NULL,
  `status` VARCHAR(10) NOT NULL,
  `asked_at` DATETIME NULL,
  `answered_at` DATETIME NULL,
  PRIMARY KEY (`coach_id`, `athlete_id`),
  KEY `ach_consent_athlete` (`athlete_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Share of active users with each level, counted at night
CREATE TABLE IF NOT EXISTS `ach_rarity` (
  `role` CHAR(1) NOT NULL,
  `achievement` VARCHAR(32) NOT NULL,
  `level` TINYINT NOT NULL,
  `pct` DOUBLE NOT NULL,
  PRIMARY KEY (`role`, `achievement`, `level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- An athlete's results as the coach achievements read them (JSON), kept by the athlete recount
CREATE TABLE IF NOT EXISTS `ach_fact` (
  `user_id` BIGINT NOT NULL,
  `facts` MEDIUMTEXT NOT NULL,
  `updated_at` DATETIME NULL,
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Users to recount by the worker
CREATE TABLE IF NOT EXISTS `ach_queue` (
  `user_id` BIGINT NOT NULL,
  `role` CHAR(1) NOT NULL,
  `queued_at` DATETIME NULL,
  PRIMARY KEY (`user_id`, `role`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Levels taken away by a moderator (cheating), with the reason
CREATE TABLE IF NOT EXISTS `ach_log` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT NOT NULL,
  `role` CHAR(1) NOT NULL,
  `achievement` VARCHAR(32) NOT NULL,
  `from_level` TINYINT NOT NULL,
  `to_level` TINYINT NOT NULL,
  `reason` VARCHAR(255) NOT NULL,
  `created_at` DATETIME NULL,
  PRIMARY KEY (`id`),
  KEY `ach_log_user` (`user_id`, `role`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Small settings the code keeps: worker time, data seen on the site, the id key
CREATE TABLE IF NOT EXISTS `ach_meta` (
  `k` VARCHAR(64) NOT NULL,
  `v` TEXT NULL,
  PRIMARY KEY (`k`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
